/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's rich type system with:
 * - Variance annotations (covariant/contravariant)
 * - Sealed trait ADTs for union types and enumerations
 * - Type classes for structural typing (replacing Python's Protocol)
 * - Pattern matching for type dispatch
 * - Immutable data with case classes
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import scala.util.Try

// ============================================================================
// Type Classes (replacing Python's Protocol / structural typing)
// ============================================================================

/** Type class for objects that can be converted to a token string. */
trait Tokenizable[A] {
  def toToken(a: A): String
}

/** Type class for objects that have a length. */
trait HasLength[A] {
  def length(a: A): Int
}

/** Contravariant processor that consumes tokens. */
trait TokenProcessor[-A] {
  def process(item: A): Unit
}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object StringType extends TokenType { val value = "string" }
