    s.replace("\\", "\\\\")
      .replace("\"", "\\\"")
      .replace("\n", "\\n")
      .replace("\r", "\\r")
      .replace("\t", "\\t")

  private def render(value: JsonValue): String = value match {
    case JsonString(s) => s""""${escapeJson(s)}""""
    case JsonNumber(n) =>
      if (n.isWhole) n.toLong.toString else n.toString
    case JsonBool(b)      => b.toString
    case JsonNull          => "null"
    case JsonArray(items)  => items.map(render).mkString("[", ", ", "]")
    case JsonObject(fields) =>
      fields.map { case (k, v) => s""""${escapeJson(k)}": ${render(v)}""" }
        .mkString("{", ", ", "}")
  }

  private def renderPretty(value: JsonValue, indent: Int = 0): String = {
    val pad = "  " * indent
    val padInner = "  " * (indent + 1)
    value match {
      case JsonString(s) => s""""${escapeJson(s)}""""
      case JsonNumber(n) =>
        if (n.isWhole) n.toLong.toString else n.toString
      case JsonBool(b)      => b.toString
      case JsonNull          => "null"
      case JsonArray(items) if items.isEmpty => "[]"
      case JsonArray(items) =>
        items
          .map(item => padInner + renderPretty(item, indent + 1))
          .mkString("[\n", ",\n", s"\n$pad]")
      case JsonObject(fields) if fields.isEmpty => "{}"
      case JsonObject(fields) =>
        fields
          .map { case (k, v) =>
            s"""$padInner"${escapeJson(k)}": ${renderPretty(v, indent + 1)}"""
          }
          .mkString("{\n", ",\n", s"\n$pad}")
    }
  }

  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) renderPretty(value) else render(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")

    val result = parts.foldLeft(Option(value)) {
      case (None, _) => None
      case (Some(JsonObject(fields)), part) => fields.get(part)
      case (Some(JsonArray(items)), part) =>
        Try(part.toInt).toOption.flatMap { idx =>
          if (idx >= 0 && idx < items.size) Some(items(idx)) else None
        }
      case _ => None
    }

    result.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 *
 * A fundamental tokenization operation used in NLP and text processing.
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] =
    ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) return None

    maxLength.foreach { max =>
      if (processed.length > max) {
        processed = processed.take(max)
      }
    }

    if (processed.isEmpty) None else Some(processed)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.StringType,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    var currentPos = 0
    val result = List.newBuilder[(String, Int, Int)]

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.result()
  }

  def countTokens(text: String): Int =
    tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Immutable fluent builder for creating tokenizers.
 *
 * Uses Scala's case class copy to implement an immutable builder pattern,
 * in contrast to Python's mutable builder.
 */
case class TokenizerBuilder[T](
  normalizers: List[String => String] = Nil,
  validators: List[T => Boolean] = Nil,
  metadata: Map[String, Any] = Map.empty
) {
  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] =
    copy(normalizers = normalizers :+ normalizer)

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] =
    copy(validators = validators :+ validator)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] =
    copy(metadata = metadata ++ entries.toMap)

  def build(): T => Token = {
    val capturedNormalizers = normalizers
    val capturedValidators = validators
    val capturedMetadata = metadata

    (value: T) => {
      capturedValidators.foreach { validator =>
        if (!validator(value))
          throw new IllegalArgumentException(s"Validation failed for $value")
      }

      var strValue = value.toString
      capturedNormalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.StringType, capturedMetadata)
    }
  }
}
